import * as cheerio from "cheerio";
import type { SitePage } from "./types.js";

/**
 * Everything the checks need from one page, extracted once.
 *
 * Parsing happens here and nowhere else, for two reasons. Real small-business HTML is frequently
 * malformed — unclosed tags, stray quotes, markup generated by a page builder from 2013 — and a
 * parser tolerates that where a regex quietly matches the wrong thing. And a check that did its
 * own extraction would be a check whose correctness depends on a regex nobody reviews; here the
 * extraction is one reviewed surface that thirty checks share.
 */
export interface PageFacts {
  url: string;
  role: SitePage["role"];
  title: string | null;
  metaDescription: string | null;
  /** `<meta name="robots">` content, lowercased. */
  metaRobots: string | null;
  /** The X-Robots-Tag header, lowercased. */
  xRobotsTag: string | null;
  metaGenerator: string | null;
  hasViewportMeta: boolean;
  /** A `@media` rule in an inline <style>, or a media-qualified stylesheet link. */
  hasResponsiveCss: boolean;
  hasIconLink: boolean;
  headings: string[];
  /** Visible text, scripts and styles removed, whitespace collapsed. */
  text: string;
  /** Size of the served markup. Meaningful only next to `text.length` — see coverage.ts. */
  htmlBytes: number;
  /** The raw HTML, lowercased once — several detectors match against script contents. */
  haystack: string;
  telHrefs: string[];
  mailtoHrefs: string[];
  linkHrefs: string[];
  /** The words on links and buttons — what K8 reads to find "Get a quote" or "Book now". */
  ctaTexts: string[];
  /** Text inside an `<address>` element, the one tag that says "this is an address". */
  addressElementText: string | null;
  scriptSrcs: string[];
  iframeSrcs: string[];
  images: { total: number; withAlt: number };
  forms: { total: number; withMessageField: number };
  /** Every @type string found in JSON-LD blocks, plus microdata itemtypes. */
  schemaTypes: string[];
  /** Whether any JSON-LD block declared opening hours. */
  schemaHasOpeningHours: boolean;
  /** Whether any JSON-LD block declared a PostalAddress. */
  schemaHasPostalAddress: boolean;
  /**
   * Names the site's own structured data attributes to a person who owns or founded the business
   * — `founder`, or a `Person` given as `employee`/`author` of the organisation itself.
   *
   * Only ever what the markup states outright. A capitalised word near the About heading is a
   * guess, and a guessed owner name is worse than none: the operator opens a call with it and is
   * immediately wrong about who they are speaking to.
   */
  ownerNames: string[];
  /** ISO-ish date strings from JSON-LD dateModified / article:modified_time meta tags. */
  modifiedDates: string[];
  /** Every four-digit year appearing next to a copyright marker. */
  copyrightYears: number[];
}

export function parsePage(page: SitePage): PageFacts {
  const $ = cheerio.load(page.html);

  // Scripts and styles are removed from the *text* view but kept in `haystack`: their contents
  // are noise when reading a page and are exactly where tracking tags live when detecting one.
  const $text = cheerio.load(page.html);
  $text("script, style, noscript, template").remove();
  const text = visibleText($text);

  const attr = (selector: string, name: string): string | null => {
    const value = $(selector).first().attr(name);
    return typeof value === "string" && value.trim().length > 0 ? value.trim() : null;
  };

  const linkHrefs = uniqueStrings($("a[href]").map((_, el) => $(el).attr("href") ?? "").get());
  const jsonLd = readJsonLd($);

  const images = $("img");
  let withAlt = 0;
  let countedImages = 0;
  images.each((_, el) => {
    const $el = $(el);
    // Decorative images are correctly marked with an empty alt; counting them as failures would
    // penalise the sites that got accessibility *right*.
    if ($el.attr("aria-hidden") === "true" || $el.attr("role") === "presentation") return;
    countedImages += 1;
    const alt = $el.attr("alt");
    if (typeof alt === "string" && alt.trim().length > 0) withAlt += 1;
  });

  let formsWithMessage = 0;
  $("form").each((_, el) => {
    const $form = $(el);
    if ($form.find("textarea").length > 0) {
      formsWithMessage += 1;
      return;
    }
    const named = $form
      .find("input, select")
      .map((_i, input) => `${$(input).attr("name") ?? ""} ${$(input).attr("id") ?? ""} ${$(input).attr("placeholder") ?? ""}`)
      .get()
      .join(" ")
      .toLowerCase();
    if (/message|comment|enquir|inquir|details|how can we help|your needs|project/i.test(named)) {
      formsWithMessage += 1;
    }
  });

  const inlineStyles = $("style").text();
  const mediaQualifiedLink = $("link[rel~='stylesheet'][media]")
    .filter((_, el) => {
      const media = ($(el).attr("media") ?? "").toLowerCase();
      return media.length > 0 && media !== "all" && media !== "screen";
    })
    .length > 0;

  return {
    url: page.url,
    role: page.role,
    title: collapseOrNull($("title").first().text()),
    metaDescription: attr('meta[name="description" i]', "content"),
    metaRobots: lower(attr('meta[name="robots" i]', "content")),
    xRobotsTag: lower(page.xRobotsTag ?? null),
    metaGenerator: attr('meta[name="generator" i]', "content"),
    hasViewportMeta: $('meta[name="viewport" i]').length > 0,
    hasResponsiveCss: /@media\b/i.test(inlineStyles) || mediaQualifiedLink,
    hasIconLink: $('link[rel~="icon" i], link[rel="shortcut icon" i], link[rel="apple-touch-icon" i], link[rel="mask-icon" i]').length > 0,
    headings: uniqueStrings($("h1, h2").map((_, el) => collapse($(el).text())).get()).slice(0, 30),
    text,
    htmlBytes: page.html.length,
    haystack: page.html.toLowerCase(),
    telHrefs: linkHrefs.filter((href) => /^tel:/i.test(href)),
    mailtoHrefs: linkHrefs.filter((href) => /^mailto:/i.test(href)),
    linkHrefs,
    ctaTexts: uniqueStrings(
      $("a, button, input[type='submit'], input[type='button']")
        .map((_, el) => collapse($(el).text() || $(el).attr("value") || $(el).attr("aria-label") || ""))
        .get(),
    ).slice(0, 200),
    addressElementText: collapseOrNull($("address").first().text()),
    scriptSrcs: uniqueStrings($("script[src]").map((_, el) => $(el).attr("src") ?? "").get()),
    iframeSrcs: uniqueStrings($("iframe[src]").map((_, el) => $(el).attr("src") ?? "").get()),
    images: { total: countedImages, withAlt },
    forms: { total: $("form").length, withMessageField: formsWithMessage },
    schemaTypes: uniqueStrings([
      ...jsonLd.types,
      ...$("[itemtype]").map((_, el) => $(el).attr("itemtype") ?? "").get(),
    ]),
    schemaHasOpeningHours: jsonLd.hasOpeningHours,
    schemaHasPostalAddress: jsonLd.hasPostalAddress,
    ownerNames: uniqueStrings(jsonLd.ownerNames),
    modifiedDates: uniqueStrings([
      ...jsonLd.modifiedDates,
      ...$('meta[property="article:modified_time" i], meta[name="last-modified" i], meta[property="og:updated_time" i]')
        .map((_, el) => $(el).attr("content") ?? "")
        .get(),
    ]),
    copyrightYears: extractCopyrightYears(text),
  };
}

/**
 * The page's visible text, with every text node separated by a space.
 *
 * Cheerio's own `.text()` concatenates nodes with **no separator at all**, so
 * `<h2>What our customers say</h2><p>Great work!</p>` comes back as `"...sayGreat work!"` — two
 * words fused into one that matches nothing. That silently breaks every check that reads the
 * page as prose: opening hours, addresses, phone numbers written across `<span>`s, and the
 * testimonial heading that first exposed it. Joining on whitespace can occasionally split a word
 * that was styled mid-way through, which costs a match on a rare page; failing to separate costs
 * matches on ordinary ones.
 */
function visibleText($: cheerio.CheerioAPI): string {
  const parts: string[] = [];
  const roots = $("body").length > 0 ? $("body").toArray() : $.root().toArray();
  for (const root of roots) collectText(root as unknown as DomNode, parts, 0);
  return collapse(parts.join(" "));
}

interface DomNode {
  type?: string;
  name?: string;
  data?: string;
  children?: DomNode[];
}

const NON_TEXT_TAGS = new Set(["script", "style", "noscript", "template"]);

function collectText(node: DomNode, parts: string[], depth: number): void {
  if (depth > 100 || !node) return;
  if (node.type === "text") {
    const data = node.data ?? "";
    if (data.trim().length > 0) parts.push(data);
    return;
  }
  if (node.name && NON_TEXT_TAGS.has(node.name)) return;
  for (const child of node.children ?? []) collectText(child, parts, depth + 1);
}

interface JsonLdFacts {
  types: string[];
  hasOpeningHours: boolean;
  hasPostalAddress: boolean;
  modifiedDates: string[];
  /** Names the markup explicitly attributes to a founder or owner. */
  ownerNames: string[];
}

/**
 * Walks every `application/ld+json` block. Structured data is worth the effort over a text search
 * because it is the one part of a page that says what it means: a site declaring
 * `"@type": "Dentist"` has LocalBusiness markup by definition, where the word "dentist" in the
 * body text says nothing at all.
 *
 * A malformed block is skipped silently. Publishers ship broken JSON-LD constantly, and one bad
 * block must not cost us the good ones next to it.
 */
function readJsonLd($: cheerio.CheerioAPI): JsonLdFacts {
  const facts: JsonLdFacts = { types: [], hasOpeningHours: false, hasPostalAddress: false, modifiedDates: [], ownerNames: [] };

  $('script[type="application/ld+json" i]').each((_, el) => {
    const raw = $(el).text();
    if (!raw || raw.trim().length === 0) return;
    let parsed: unknown;
    try {
      parsed = JSON.parse(raw);
    } catch {
      return;
    }
    walkJsonLd(parsed, facts, 0);
  });

  return facts;
}

/** Pulls the `name` out of a Person node, or an array of them. Anything else is ignored. */
function collectPersonNames(value: unknown, into: string[]): void {
  if (typeof value === "string") {
    if (value.trim().length > 0) into.push(value.trim());
    return;
  }
  if (Array.isArray(value)) {
    for (const item of value) collectPersonNames(item, into);
    return;
  }
  if (value !== null && typeof value === "object") {
    const name = (value as { name?: unknown }).name;
    if (typeof name === "string" && name.trim().length > 0) into.push(name.trim());
  }
}

function walkJsonLd(node: unknown, facts: JsonLdFacts, depth: number): void {
  if (depth > 8 || node === null || typeof node !== "object") return;

  if (Array.isArray(node)) {
    for (const item of node) walkJsonLd(item, facts, depth + 1);
    return;
  }

  const record = node as Record<string, unknown>;
  const type = record["@type"];
  if (typeof type === "string") facts.types.push(type);
  if (Array.isArray(type)) for (const t of type) if (typeof t === "string") facts.types.push(t);

  if ("openingHours" in record || "openingHoursSpecification" in record) facts.hasOpeningHours = true;
  if (typeof type === "string" && type === "PostalAddress") facts.hasPostalAddress = true;
  if ("address" in record && typeof record["address"] === "object" && record["address"] !== null) {
    facts.hasPostalAddress = true;
  }
  for (const key of ["dateModified", "datePublished", "uploadDate"]) {
    const value = record[key];
    if (typeof value === "string") facts.modifiedDates.push(value);
  }

  // `founder` is the one relationship schema.org gives that means exactly "this person started
  // this business". A bare `Person` elsewhere in the graph could be a review author or a blog
  // writer, so it is not treated as an owner.
  for (const key of ["founder", "founders"]) {
    collectPersonNames(record[key], facts.ownerNames);
  }

  for (const value of Object.values(record)) walkJsonLd(value, facts, depth + 1);
}

/**
 * Years appearing within a short window of a copyright marker. The window matters: a page
 * mentioning "since 1998" in its body copy and "© 2026" in its footer must yield 2026, and a
 * naive "any four-digit year" scan would happily return 1998 and call the site abandoned.
 */
function extractCopyrightYears(text: string): number[] {
  const years = new Set<number>();
  const pattern = /(?:©|&copy;|\(c\)|copyright)([^.|]{0,40})/gi;
  for (const match of text.matchAll(pattern)) {
    const window = match[1] ?? "";
    for (const yearMatch of window.matchAll(/\b(19|20)\d{2}\b/g)) {
      const year = Number(yearMatch[0]);
      if (year >= 1990 && year <= 2100) years.add(year);
    }
  }
  return [...years].sort((a, b) => a - b);
}

function collapse(value: string): string {
  return value.replace(/\s+/g, " ").trim();
}

function collapseOrNull(value: string): string | null {
  const collapsed = collapse(value);
  return collapsed.length > 0 ? collapsed : null;
}

function lower(value: string | null): string | null {
  return value === null ? null : value.toLowerCase();
}

function uniqueStrings(values: string[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const value of values) {
    const trimmed = value.trim();
    if (trimmed.length === 0 || seen.has(trimmed)) continue;
    seen.add(trimmed);
    out.push(trimmed);
  }
  return out;
}
